import{_ as a,C as o,o as s,c as n,j as t,a as i,E as d,ak as h}from"./chunks/framework.sV-XtlWr.js";const l="/screenshots/report-schedules.png",b=JSON.parse('{"title":"Quality reports","description":"","frontmatter":{"title":"Quality reports","lang":"en-US"},"headers":[],"relativePath":"features/quality-reports.md","filePath":"features/quality-reports.md","lastUpdated":1790416336000}'),c={name:"features/quality-reports.md"};function p(u,e,g,m,f,y){const r=o("Needs");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"quality-reports",tabindex:"-1"},[i("Quality reports "),t("a",{class:"header-anchor",href:"#quality-reports","aria-label":'Permalink to "Quality reports"'},"​")],-1)),d(r,{reporter:""}),e[1]||(e[1]=h('<p>A <strong>quality report</strong> is a document about the state of one or several projects over a period, written for a reader who may never open the dashboard: a manager, a release owner, a client. It is not the Playwright HTML report a run carries (the <strong>run report</strong>); it is the <a href="./analytics.html">Analytics</a> page turned into something you can send.</p><h2 id="what-a-report-contains" tabindex="-1">What a report contains <a class="header-anchor" href="#what-a-report-contains" aria-label="Permalink to &quot;What a report contains&quot;">​</a></h2><p>A report renders a <strong>dashboard</strong>, an arrangement of analytics widgets in bands, over a <strong>scope</strong>: the projects, branches, environments, test filter and period of the analytics <strong>Filters</strong> block. Any <a href="./dashboards.html">saved dashboard</a> can be exported and scheduled; two built-in dashboards exist for reports:</p><ul><li><p><strong>Executive</strong>, for stakeholders, in plain words with no locators and no stack traces: a verdict, six headline numbers, the pass rate over time with the comparison period and your <a href="./timeline-markers.html">timeline markers</a>, what changed, what is being done (causes fixed, assigned or ticketed, tests released from quarantine) and the risks (metrics moving the wrong way, projects failing run after run, the oldest open causes).</p></li><li><p><strong>Engineering</strong>, for the team that owns the suite: the executive report, then the flakiest tests, the failure clusters, wasted CI time, regressions, CI time, the browser matrix and slow endpoints.</p></li><li><p><strong>Team</strong>, the engineering report for the tests one owner holds (<code>piwi:owner</code> or CODEOWNERS), offered when a test in scope has an owner.</p></li><li><p><strong>Gaps digest</strong>, the <a href="./scenario-gaps.html">Test Map</a>&#39;s weekly digest: the top five new gaps of each project, then open gaps by class and feature. A project that declined the Test Map is left out.</p></li></ul><p>The engineering report ends with the same gap counts. <strong>Overview</strong>, the analytics page itself, can be exported too.</p><p>Every report ends with a footer stating the scope, the branch policy, the period and its comparison, each metric&#39;s definition, and its limits: lists of tests reach back only as far as <a href="/operate/storage.html#data-retention">retention</a> keeps runs, and days are UTC.</p><h3 id="the-verdict-is-built-by-rules" tabindex="-1">The verdict is built by rules <a class="header-anchor" href="#the-verdict-is-built-by-rules" aria-label="Permalink to &quot;The verdict is built by rules&quot;">​</a></h3><p>The opening sentence (&quot;The pass rate on main fell 2.1 points to 95.8%, and 3 failure causes were fixed.&quot;) comes from fixed rules over the numbers, never from a model. Its tone is <strong>good</strong> at a pass rate of 90% or more that did not drop by more than a point, <strong>bad</strong> under 50% or after a drop of 5 points or more, <strong>mixed</strong> otherwise.</p><h2 id="exporting-a-report" tabindex="-1">Exporting a report <a class="header-anchor" href="#exporting-a-report" aria-label="Permalink to &quot;Exporting a report&quot;">​</a></h2><p>Click <strong>Export</strong> on the Analytics page (the current scope) or on a project page (that project, last 30 days). The dialog previews the report; pick another dashboard or the language, then <strong>Download</strong>:</p><table tabindex="0"><thead><tr><th>Format</th><th>What you get</th></tr></thead><tbody><tr><td>PDF</td><td>Vector text and charts, one band per page so pages drop into a slide deck</td></tr><tr><td>HTML</td><td>One self-contained file: inline charts, no script, no remote resource</td></tr><tr><td>Markdown</td><td>Tables, and a text sparkline (<code>▁▂▃▅▇</code>) under each series; pastes into Confluence, Jira or a pull request</td></tr><tr><td>Excel</td><td>An .xlsx workbook, a sheet per table named after its widget; numbers and dates are real cells, text never runs as a formula. Each section&#39;s <strong>Excel</strong> button downloads just that section</td></tr><tr><td>JSON</td><td>The report bundle itself, for scripts and BI tools</td></tr></tbody></table><p>Scripts can ask the API for <code>format=csv</code>, formula-guarded with a leading <code>&#39;</code>.</p><p>A report grants no access: it covers only the projects its reader can open.</p><h2 id="report-schedules" tabindex="-1">Report schedules <a class="header-anchor" href="#report-schedules" aria-label="Permalink to &quot;Report schedules&quot;">​</a></h2><p>A <strong>report schedule</strong> sends a quality report on its own. <strong>Schedule…</strong> on the Analytics page or in a project page&#39;s menu opens the form with the filters on screen; <strong>New schedule</strong> on the <strong>Quality reports</strong> page starts an empty one. Reporters and administrators create schedules.</p><p><img src="'+l+'" alt="The Quality reports page: report snapshots and schedules"></p><ul><li><strong>When</strong>: daily, weekly, every other week or monthly, at a time in the instance time zone (UTC when that setting follows each browser).</li><li><strong>Which period</strong>: the whole days since the previous report, so a weekly Monday schedule reports on Monday to Sunday; the first one covers the days since you created it. A period with no run is still sent, because a stopped pipeline is news.</li><li><strong>Where</strong>: <a href="./notifications.html">notification channels</a>. Email carries the verdict, the numbers and the trend as an image; Slack and Microsoft Teams the same as a message; a webhook the whole bundle as signed JSON; a browser channel a notification. With <strong>Share link</strong> on, each report carries a <a href="./share-links.html#report-share-links">share link</a> that opens it without an account. <strong>AI narrative</strong> adds the <a href="./analytics-widgets.html#where-things-stand">narrative</a> the AI model writes.</li></ul><p><strong>Run now</strong> sends the last complete period straight away; <strong>Preview</strong>, in the form, shows that report before you save, as its email and as the full report, and sends nothing. <strong>Mute</strong> keeps the snapshots and sends nothing; <strong>Pause</strong> stops the schedule. Each firing uses its owner&#39;s current project access. A <strong>global</strong> schedule covers every project, goes to global channels and needs an administrator.</p><p>The server checks schedules every five minutes; a firing missed while it was down happens at the next check, for its own period. The <a href="./desktop.html">desktop app</a> fires them while it runs; the demo has no scheduler.</p><h3 id="report-snapshots" tabindex="-1">Report snapshots <a class="header-anchor" href="#report-snapshots" aria-label="Permalink to &quot;Report snapshots&quot;">​</a></h3><p>Every report sent is kept as a <strong>report snapshot</strong> with its numbers as they were: a report received in March reads the same in June, whatever <a href="/operate/storage.html#data-retention">retention</a> deleted since. The <strong>Quality reports</strong> page lists them with how each was delivered, to read, download or <a href="./share-links.html#report-share-links">share</a>. You see a snapshot when you can open every project it covers. Snapshots go after <code>PIWI_RETENTION_REPORT_DAYS</code> days (365; 0 keeps them).</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Reports come in English and French: by default the project&#39;s <a href="./issue-tracking.html#language">ticket language</a> over one project, else the instance locale. Test titles and error messages stay as recorded.</p><h2 id="cost-of-a-ci-minute" tabindex="-1">Cost of a CI minute <a class="header-anchor" href="#cost-of-a-ci-minute" aria-label="Permalink to &quot;Cost of a CI minute&quot;">​</a></h2><p>An administrator can give a CI minute a price in <strong>Settings → Performance</strong>: an amount and an ISO 4217 currency, such as 0.008 USD. <code>PIWI_CI_MINUTE_COST</code> (<code>&quot;0.008 USD&quot;</code>) pins it and makes the setting read-only. Once set, every wasted-time number is followed by its cost, on the analytics page and in the quality report; unset, only minutes show. The cost is one instance-wide value.</p><h2 id="from-ci-an-agent-or-a-script" tabindex="-1">From CI, an agent or a script <a class="header-anchor" href="#from-ci-an-agent-or-a-script" aria-label="Permalink to &quot;From CI, an agent or a script&quot;">​</a></h2><ul><li>The <a href="/reference/cli.html#report"><code>piwi report</code></a> command prints a report with an API key, so a scheduled CI job can post the Markdown every Monday: <code>npx @piwitests/reporter report --project checkout --period 7d --format md</code>. <code>--fail-on bad</code> makes it exit 1 on a bad verdict.</li><li>The <a href="./mcp.html">MCP server</a> offers <code>get_quality_report</code> (the bundle), <code>get_metric_trend</code> (one metric over time) and <code>compare_periods</code> (the headline numbers over two periods).</li><li><code>GET /api/reports/preview</code> takes the dashboard, the format, the language and the analytics scope keys; <code>/api/reports/schedules</code> (<code>POST …/preview</code> for an unsaved one) and <code>/api/reports/snapshots</code> manage schedules and read snapshots. See the in-app API reference at <code>/docs</code>.</li></ul><h2 id="turning-reports-off" tabindex="-1">Turning reports off <a class="header-anchor" href="#turning-reports-off" aria-label="Permalink to &quot;Turning reports off&quot;">​</a></h2><p>Quality reports are an optional <a href="/guide/getting-started.html#declining-a-capability">capability</a>. Declining it in Setup hides the <em>Export</em> and <em>Schedule…</em> actions and the <em>Quality reports</em> page, and drops <code>get_quality_report</code> from the MCP tools; the analytics page and the metric tools stay, since analytics is core. A schedule or a snapshot counts as use, so the capability stays on while one exists: delete them first.</p>',29))])}const k=a(c,[["render",p]]);export{b as __pageData,k as default};
